import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
mkdirSync("scenario-packages", { recursive: true });
const packs = readdirSync("scenario-packages")
  .filter((n) => n.endsWith(".json"))
  .sort()
  .map((n) => JSON.parse(readFileSync("scenario-packages/" + n, "utf8")));
mkdirSync("src/generated", { recursive: true });
writeFileSync(
  "src/generated/packages.ts",
  '// Generated by npm run bundle:packages. Retain released versions for existing runs.\nexport const publishedPackages: import("../packages.ts").ScenarioPackage[] = ' +
    JSON.stringify(packs, null, 2) +
    ";\n",
);
